        if(val % 4 == 0) k = val / 4;
        else {
            x0 = -1;
            val = s + (p - 1) - x0;
            k = val / 4;
        }

        seqs[i][0] = x0;
        int half[84];
        for(int j=0; j<m; j++) {
            half[j] = (j < k) ? 1 : -1;
        }
        // shuffle
        for(int j=m-1; j>0; j--) {
            int r = rand() % (j + 1);
            int tmp = half[j];
            half[j] = half[r];
            half[r] = tmp;
        }

        for(int j=0; j<m; j++) {
            seqs[i][j+1] = half[j];
            seqs[i][p-1-j] = half[j];
        }

        // compute initial paf
        for(int _k=1; _k<=m; _k++) {
            int sum = 0;
            for(int j=0; j<p; j++) {
                sum += seqs[i][j] * seqs[i][(j+_k)%p];
            }
            pafs[i][_k] = sum;
            paf_sum[_k] += sum;
        }
    }

    for(int _k=1; _k<=m; _k++) {
        current_defect += 2 * paf_sum[_k] * paf_sum[_k];
    }

    int best_defect = current_defect;
    for(int i=0; i<4; i++) {
        for(int j=0; j<p; j++) {
            out_seqs[i*p + j] = seqs[i][j];
        }
    }

    double T0 = current_defect * 0.003;
    if(T0 < 20.0) T0 = 20.0;

    int accept_count = 0;

    for(int iter=0; iter<max_iter; iter++) {
        double frac = (double)iter / (double)max_iter;
        double T = T0 * (1.0 - frac);
        if(T < 0.01) T = 0.01;

        int seq_idx = rand() % 4;
        int *seq = seqs[seq_idx];

        // find pos +1 and -1 in half 1..m
        int pos_plus[84];
        int pos_minus[84];
        int n_plus = 0;
        int n_minus = 0;

        for(int j=1; j<=m; j++) {
