            else pos_minus[n_minus++] = j;
        }

        if(n_plus == 0 || n_minus == 0) continue;

        int j1 = pos_plus[rand() % n_plus];
        int j2 = pos_minus[rand() % n_minus];
        int j1m = p - j1;
        int j2m = p - j2;

        int changed[4] = {j1, j1m, j2, j2m};
        int dvals[4] = {-2, -2, 2, 2};

        int delta_paf[84] = {0};

        for(int c=0; c<4; c++) {
            int idx = changed[c];
            int d = dvals[c];
            for(int _k=1; _k<=m; _k++) {
                int idx_plus_k = (idx + _k) % p;
                int idx_minus_k = (idx - _k + p) % p;

                int val1 = seq[idx_minus_k];
                int val2 = seq[idx_plus_k];

                // add delta if the forward position is also changed
                int delta_at = 0;
                if(idx_plus_k == j1 || idx_plus_k == j1m) delta_at = -2;
                else if(idx_plus_k == j2 || idx_plus_k == j2m) delta_at = 2;

                delta_paf[_k] += d * (val1 + val2 + delta_at);
            }
        }

        int new_defect = 0;
        for(int _k=1; _k<=m; _k++) {
            int sum_k = paf_sum[_k] + delta_paf[_k];
            new_defect += 2 * sum_k * sum_k;
        }

        int delta_d = new_defect - current_defect;
        if(delta_d <= 0 || ((double)rand() / RAND_MAX) < exp(-delta_d / T)) {
            // accept
            seq[j1] = -1;
            seq[j1m] = -1;
            seq[j2] = 1;
            seq[j2m] = 1;

            for(int _k=1; _k<=m; _k++) {
                pafs[seq_idx][_k] += delta_paf[_k];
                paf_sum[_k] += delta_paf[_k];
