                    }
                }
                if(best_defect == 0) {
                    printf("FOUND at iter %d!\\n", iter);
                    break;
                }
            }
        }
    }

    printf("Final defect: %d, Accepted: %d\\n", best_defect, accept_count);

    for(int i=0; i<4; i++) {
        free(seqs[i]);
        free(pafs[i]);
    }
}
"""

with open("sa.c", "w") as f:
    f.write(c_code)

os.system("gcc -O3 -shared -fPIC sa.c -o libsa.so -lm")

lib = ctypes.CDLL("./libsa.so")
lib.sa_search.argtypes = [ctypes.c_int, ctypes.c_int, ctypes.POINTER(ctypes.c_int), ctypes.POINTER(ctypes.c_int), ctypes.c_int, ctypes.c_int]

def run_c_sa(targets, max_iter=100000000, seed=42):
    p = 167
    m = (p - 1) // 2

    t_arr = (ctypes.c_int * 4)(*targets)
    out_arr = (ctypes.c_int * (4 * p))()

    lib.sa_search(p, m, t_arr, out_arr, max_iter, seed)

    best_seqs = np.array(out_arr).reshape((4, p))
    return best_seqs

# Try a few sum options with 100M iterations each
targets_list = [
    [3, 3, 5, 25],
    [3, 7, 13, 21],
    [1, 1, 15, 21],
    [3, 3, 17, 19],
    [23, 9, 7, 3],
    [25, 5, 3, 3]
]

for t in targets_list:
    print(f"\nRunning C SA for {t}")
    start = time.time()
    best_seqs = run_c_sa(t, max_iter=50000000, seed=np.random.randint(100000))
    print(f"Time: {time.time()-start:.2f}s")
