import os
import ctypes
import numpy as np
import time

p = 167

c_code = """
#include <stdlib.h>
#include <stdio.h>
#include <math.h>

void sa_gs(int p, int *init_seqs, int *out_seqs, int max_iter, int seed) {
    srand(seed);
    int *seqs[4];
    int *pafs[4];
    int paf_sum[167] = {0}; // up to p=167

    // allocate and init
    for(int i=0; i<4; i++) {
        seqs[i] = (int*)malloc(p * sizeof(int));
        pafs[i] = (int*)malloc(p * sizeof(int));
        for(int j=0; j<p; j++) {
            seqs[i][j] = init_seqs[i*p + j];
        }
    }

    // compute initial pafs
    for(int i=0; i<4; i++) {
        for(int k=1; k<p; k++) {
            int sum = 0;
            for(int j=0; j<p; j++) {
                sum += seqs[i][j] * seqs[i][(j+k)%p];
            }
            pafs[i][k] = sum;
            paf_sum[k] += sum;
        }
    }

    int current_defect = 0;
    for(int k=1; k<p; k++) {
        current_defect += paf_sum[k] * paf_sum[k]; // No longer multiply by 2, we sum over all 1..p-1
    }

    int best_defect = current_defect;
    for(int i=0; i<4; i++) {
        for(int j=0; j<p; j++) {
            out_seqs[i*p + j] = seqs[i][j];
        }
    }

    double T0 = current_defect * 0.05;
    if(T0 < 5.0) T0 = 5.0;

    int accept_count = 0;

    for(int iter=0; iter<max_iter; iter++) {
        double frac = (double)iter / (double)max_iter;
        double T = T0 * (1.0 - frac);
        if(T < 0.01) T = 0.01;

        int seq_idx = rand() % 4;
        int *seq = seqs[seq_idx];

        // Pick a random bit to flip
        int j1 = rand() % p;
        int val_old = seq[j1];
        int d = (val_old == 1) ? -2 : 2;

        int delta_paf[167] = {0};

        // PAF[k] change:
        // old: seq[j1]*seq[j1+k] + seq[j1-k]*seq[j1]
        // new: (seq[j1]+d)*seq[j1+k] + seq[j1-k]*(seq[j1]+d)
        // delta: d * (seq[j1+k] + seq[j1-k])
        for(int k=1; k<p; k++) {
            int idx_plus = (j1 + k) % p;
            int idx_minus = (j1 - k + p) % p;
            delta_paf[k] = d * (seq[idx_plus] + seq[idx_minus]);
        }

        int new_defect = 0;
        for(int k=1; k<p; k++) {
            int new_sum = paf_sum[k] + delta_paf[k];
            new_defect += new_sum * new_sum;
        }

        int delta_d = new_defect - current_defect;

        if(delta_d <= 0 || ((double)rand() / RAND_MAX) < exp(-delta_d / T)) {
            seq[j1] = val_old + d; // flip
            for(int k=1; k<p; k++) {
                pafs[seq_idx][k] += delta_paf[k];
                paf_sum[k] += delta_paf[k];
            }
            current_defect = new_defect;
            accept_count++;

            if(current_defect < best_defect) {
                best_defect = current_defect;
                for(int a=0; a<4; a++) {
                    for(int b=0; b<p; b++) {
                        out_seqs[a*p + b] = seqs[a][b];
                    }
                }
                if(best_defect == 0) {
                    printf("FOUND at iter %d!\\n", iter);
                    break;
                }
            }
        }
    }

    printf("Final defect: %d, Accepted: %d\\n", best_defect, accept_count);

    for(int i=0; i<4; i++) {
        free(seqs[i]);
        free(pafs[i]);
    }
}
"""

with open("sa_gs.c", "w") as f:
    f.write(c_code)

os.system("gcc -O3 -shared -fPIC sa_gs.c -o libsa_gs.so -lm")

lib = ctypes.CDLL("./libsa_gs.so")
lib.sa_gs.argtypes = [ctypes.c_int, ctypes.POINTER(ctypes.c_int), ctypes.POINTER(ctypes.c_int), ctypes.c_int, ctypes.c_int]

# Build the 4 Legendre sequences
QR = set(pow(x, 2, p) for x in range(1, p))
L = np.array([0 if i == 0 else (1 if i in QR else -1) for i in range(p)], dtype=int)
L_p = L.copy(); L_p[0] = 1
L_m = L.copy(); L_m[0] = -1

# Seed with 4 copies of L_p
init_seqs = np.array([L_p, L_p, L_p, L_p], dtype=int).flatten()

out_arr = (ctypes.c_int * (4 * p))()
in_arr = (ctypes.c_int * (4 * p))(*init_seqs.tolist())

print("\nRunning Goethals-Seidel Simulated Annealing...")
start = time.time()
lib.sa_gs(p, in_arr, out_arr, 150000000, np.random.randint(100000))
best_seqs = np.array(out_arr).reshape((4, p))
print(f"Time: {time.time()-start:.2f}s")

# Check if defect is really 0 and sum of PAFs is 0
def compute_paf(seq):
    S = np.fft.rfft(seq.astype(float))
    psd = np.abs(S)**2
    return np.round(np.fft.irfft(psd, n=len(seq))).astype(int)

pafs = np.array([compute_paf(best_seqs[i]) for i in range(4)])
paf_sum = np.sum(pafs, axis=0)
defect = int(np.sum(paf_sum[1:]**2))
print("Defect of best_seqs:", defect)
