import os
import ctypes
import numpy as np
import time

p = 167
m = (p - 1) // 2

c_code = r"""
#include <stdlib.h>
#include <stdio.h>
#include <math.h>
#include <string.h>

int tabu_search(int p, int m, int *targets, int *out_seqs, int max_iter, unsigned int seed) {
    srand(seed);
    int seqs[4][167];
    int pafs[4][84];
    int paf_sum[84];
    memset(paf_sum, 0, sizeof(paf_sum));

    // Initialize
    for(int i=0; i<4; i++) {
        int s = targets[i];
        int x0 = 1;
        int val = s + (p - 1) - x0;
        if(val % 4 != 0) { x0 = -1; val = s + (p - 1) - x0; }
        int k = val / 4;

        seqs[i][0] = x0;
        int half[84];
        for(int j=0; j<m; j++) half[j] = (j < k) ? 1 : -1;
        // Shuffle
        for(int j=m-1; j>0; j--) { int r=rand()%(j+1); int t=half[j]; half[j]=half[r]; half[r]=t; }
        for(int j=0; j<m; j++) { seqs[i][j+1] = half[j]; seqs[i][p-1-j] = half[j]; }

        for(int _k=1; _k<=m; _k++) {
            int sv = 0;
            for(int j=0; j<p; j++) sv += seqs[i][j] * seqs[i][(j+_k)%p];
            pafs[i][_k] = sv;
            paf_sum[_k] += sv;
        }
    }

    int current_defect = 0;
    for(int _k=1; _k<=m; _k++) current_defect += 2 * paf_sum[_k] * paf_sum[_k];

    int best_defect = current_defect;
    for(int i=0; i<4; i++) for(int j=0; j<p; j++) out_seqs[i*p+j] = seqs[i][j];

    // Tabu list stores the iteration when a bit is allowed to be flipped again
    int tabu_list[4][167];
    memset(tabu_list, 0, sizeof(tabu_list));
    int tabu_tenure = 50;  // Length of tabu list

    int pp[4][84], pm[4][84];
    int n_plus[4], n_minus[4];

    for(int i=0; i<4; i++) {
        n_plus[i] = 0; n_minus[i] = 0;
        for(int j=1; j<=m; j++) {
            if(seqs[i][j] == 1) pp[i][n_plus[i]++] = j;
            else pm[i][n_minus[i]++] = j;
        }
    }

    for(int iter=1; iter<=max_iter; iter++) {
        int best_move_defect = 2000000000;
        int best_seq = -1, best_j1 = -1, best_j2 = -1;
        int best_dp[84];

        // Evaluate K random neighbors
        int K = 250;
        for(int n=0; n<K; n++) {
            int seq_idx = rand() % 4;
            if(n_plus[seq_idx]==0 || n_minus[seq_idx]==0) continue;

            int c1 = rand() % n_plus[seq_idx];
            int j1 = pp[seq_idx][c1]; 
            int c2 = rand() % n_minus[seq_idx];
            int j2 = pm[seq_idx][c2]; 

            // Tabu check (allow aspiration if it beats overall best)
            int is_tabu = (tabu_list[seq_idx][j1] >= iter) || (tabu_list[seq_idx][j2] >= iter);

            int j1m = p - j1, j2m = p - j2;
            int changed[4] = {j1, j1m, j2, j2m};
            int dvals[4] = {-2, -2, 2, 2};

            int dp[84];
            memset(dp, 0, sizeof(dp));

            for(int c=0; c<4; c++) {
                int idx = changed[c]; int d = dvals[c];
                for(int _k=1; _k<=m; _k++) {
                    int ip = (idx + _k) % p;
                    int im = (idx - _k + p) % p;
                    int da = 0;
                    if(ip==j1||ip==j1m) da=-2;
                    else if(ip==j2||ip==j2m) da=2;
                    dp[_k] += d * (seqs[seq_idx][im] + seqs[seq_idx][ip] + da);
                }
            }

            int new_defect = 0;
            for(int _k=1; _k<=m; _k++) {
                int sk = paf_sum[_k] + dp[_k];
                new_defect += 2 * sk * sk;
            }

            if(!is_tabu || new_defect < best_defect) {
                if(new_defect < best_move_defect) {
                    best_move_defect = new_defect;
                    best_seq = seq_idx;
                    best_j1 = c1;
                    best_j2 = c2;
                    memcpy(best_dp, dp, sizeof(dp));
                }
            }
        }

        if(best_seq != -1) {
            int j1 = pp[best_seq][best_j1]; // +1 -> -1
            int j2 = pm[best_seq][best_j2]; // -1 -> +1

            // Apply move
            seqs[best_seq][j1] = -1; seqs[best_seq][p-j1] = -1;
            seqs[best_seq][j2] = 1;  seqs[best_seq][p-j2] = 1;

            // Update lists
            pp[best_seq][best_j1] = j2;
            pm[best_seq][best_j2] = j1;

            // Update PAFs
            for(int _k=1; _k<=m; _k++) {
                pafs[best_seq][_k] += best_dp[_k];
                paf_sum[_k] += best_dp[_k];
            }
            current_defect = best_move_defect;

            // Set tabu
            tabu_list[best_seq][j1] = iter + tabu_tenure + (rand()%10);
            tabu_list[best_seq][j2] = iter + tabu_tenure + (rand()%10);

            if(current_defect < best_defect) {
                best_defect = current_defect;
                for(int i=0; i<4; i++) for(int j=0; j<p; j++) out_seqs[i*p+j] = seqs[i][j];
                if(best_defect == 0) return 0;
            }
        }
    }
    return best_defect;
}
